//! 🗺️ Explicit GIS feature/value tables retain the complete intrinsic native domain.
use super::*;
use dsl::schema::Number;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteTable,SqliteRow,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,FloatColumn,FloatRow,insert_key_ieee754,NativeEncodingBound}}};
use std::collections::{BTreeMap,BTreeSet,VecDeque};
const TABLES:[&str;20]=["gis_map_document","gis_map_value","gis_map_position","gis_map_route","gis_map_region","gis_map_drawing_child","gis_map_image_child","gis_map_value_child","gis_map_null","gis_map_boolean","gis_map_unsigned","gis_map_signed","gis_map_float","gis_map_text","gis_map_bytes","gis_map_octet","gis_map_array","gis_map_array_element","gis_map_object","gis_map_object_member"];
const WIDTHS:[usize;20]=[1,2,5,5,5,6,6,6,1,2,3,2,4,2,1,4,1,4,1,5];
const FLOAT:&[FloatColumn]=&[FloatColumn::Binary64(1)];
fn kind(value:&dsl::DslValue)->&'static str{match value{dsl::DslValue::Null=>"null",dsl::DslValue::Bool(_)=>"boolean",dsl::DslValue::Number(Number::UInt(_))=>"unsigned",dsl::DslValue::Number(Number::Int(_))=>"signed",dsl::DslValue::Number(Number::Float(_))=>"float",dsl::DslValue::String(_)=>"text",dsl::DslValue::Bytes(_)=>"bytes",dsl::DslValue::Array(_)=>"array",dsl::DslValue::Object(_)=>"object"}}
fn add(count:&mut usize,value:usize)->Result<(),String>{*count=count.checked_add(value).ok_or("GIS entity or byte count overflow")?;Ok(())}
fn child_bytes<S>(c:&store::ArtifactChild<S>)->Result<usize,String>{let mut bytes=8;for value in[&c.child_id,&c.target.artifact_id,&c.target.dialect.artifact_kind,&c.target.dialect.standard,&c.target.dialect.subset]{add(&mut bytes,value.len())?;}Ok(bytes)}
fn child<S>(p:&mut Projection<'_,'_>,table:&str,c:&store::ArtifactChild<S>)->Result<(),String>{p.insert(table,&[Cell::Text(&c.child_id),Cell::Text(&c.target.artifact_id),Cell::Text(&c.target.dialect.artifact_kind),Cell::Text(&c.target.dialect.standard),Cell::Text(&c.target.dialect.subset)])?;Ok(())}
fn preflight(value:&GisMapSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let total=value.positions.len().checked_add(value.routes.len()).and_then(|v|v.checked_add(value.regions.len())).ok_or("GIS feature count overflow")?;let mut rows=3+usize::from(value.image.is_some());add(&mut rows,total)?;control.check_rows(rows.checked_add(total.checked_mul(2).ok_or("GIS node count overflow")?).ok_or("GIS node count overflow")?)?;let mut bytes=8+child_bytes(&value.drawing)?+child_bytes(&value.value)?;if let Some(c)=&value.image{add(&mut bytes,child_bytes(c)?)?;}control.check_value_bytes(bytes)?;let mut pending=VecDeque::with_capacity(total);for feature in value.positions.iter().chain(&value.routes).chain(&value.regions){add(&mut bytes,32+feature.id.len())?;control.check_value_bytes(bytes)?;pending.push_back(&feature.data);}let mut count=0;while let Some(value)=pending.pop_front(){add(&mut rows,2)?;add(&mut bytes,16+kind(value).len())?;let children=match value{dsl::DslValue::Array(values)=>values.len(),dsl::DslValue::Object(values)=>values.len(),_=>0};let additional=if let dsl::DslValue::Bytes(bytes)=value{bytes.len()}else{children};add(&mut rows,additional)?;control.check_rows(rows.checked_add(pending.len().checked_add(children).and_then(|n|n.checked_mul(2)).ok_or("GIS frontier row count overflow")?).ok_or("GIS frontier row count overflow")?)?;match value{dsl::DslValue::Null=>{},dsl::DslValue::Bool(_)|dsl::DslValue::Number(Number::Int(_))=>add(&mut bytes,8)?,dsl::DslValue::Number(Number::UInt(_))=>add(&mut bytes,16)?,dsl::DslValue::Number(Number::Float(v))=>add(&mut bytes,if v.is_nan(){11}else if v.is_infinite(){32}else{22})?,dsl::DslValue::String(v)=>add(&mut bytes,v.len())?,dsl::DslValue::Bytes(v)=>add(&mut bytes,v.len().checked_mul(32).ok_or("GIS octet count overflow")?)?,dsl::DslValue::Array(v)=>{add(&mut bytes,v.len().checked_mul(32).ok_or("GIS edge count overflow")?)?;control.check_value_bytes(bytes)?;pending.extend(v.iter())},dsl::DslValue::Object(v)=>{add(&mut bytes,v.len().checked_mul(32).ok_or("GIS member count overflow")?)?;for(name,_)in v{add(&mut bytes,name.len())?;control.check_value_bytes(bytes)?;}pending.extend(v.iter().map(|(_,v)|v));}}control.check_value_bytes(bytes)?;count+=1;if count%256==0{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,0)?;}}control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,count,count)}
struct Forest(Vec<Option<dsl::DslValue>>);
impl Drop for Forest{fn drop(&mut self){for value in self.0.iter_mut().filter_map(Option::take){super::owned_pack::retire_value(value)}}}
struct Items(Vec<dsl::DslValue>);impl Drop for Items{fn drop(&mut self){for v in self.0.drain(..){super::owned_pack::retire_value(v)}}}
struct Members(Vec<(String,dsl::DslValue)>);impl Drop for Members{fn drop(&mut self){for(_,v)in self.0.drain(..){super::owned_pack::retire_value(v)}}}
struct Features(Vec<MapFeature>);impl Drop for Features{fn drop(&mut self){for v in self.0.drain(..){super::owned_pack::retire_value(v.data)}}}
struct Read<'a>{tables:[&'a SqliteTable;20],maps:Vec<BTreeMap<i64,&'a SqliteRow>>,used:BTreeSet<(usize,i64)>}
impl<'a> Read<'a>{
 fn new(database:&'a SqliteDatabase,native:&mut dsl::NativeDecodeControl<'_>)->Result<Self,String>{let mut tables=native.allocate_vec::<&SqliteTable>(20)?;let mut maps=native.allocate_vec::<BTreeMap<i64,&SqliteRow>>(20)?;for(table,name)in TABLES.iter().enumerate(){let source=database.table(name)?;native.charge(source.rows.len().checked_mul(192).ok_or("GIS map lookup size overflow")?)?;let mut map=BTreeMap::new();for row in&source.rows{native.step()?;if row.values.len()!=WIDTHS[table]||row.integer(0)?!=row.rowid||map.insert(row.rowid,row).is_some(){return Err("GIS map row identity differs".into())}}tables.push(source);maps.push(map);}let tables=tables.try_into().map_err(|_|"GIS authored tables differ")?;Ok(Self{tables,maps,used:BTreeSet::new()})}
 fn take(&mut self,table:usize,key:i64,native:&mut dsl::NativeDecodeControl<'_>)->Result<&'a SqliteRow,String>{native.step()?;if !self.used.insert((table,key)){return Err("GIS entity has repeated ownership".into())}self.maps[table].get(&key).copied().ok_or_else(||"GIS entity owner is missing".into())}
 fn fixed(&mut self,table:usize,key:i64,native:&mut dsl::NativeDecodeControl<'_>)->Result<&'a SqliteRow,String>{if self.tables[table].rows.len()!=1{return Err("GIS fixed owner differs".into())}self.take(table,key,native)}
 fn child<S>(&mut self,table:usize,key:i64,native:&mut dsl::NativeDecodeControl<'_>)->Result<store::ArtifactChild<S>,String>{let row=self.fixed(table,key,native)?;Ok(store::ArtifactChild::new(native.copy_text(row.text(1)?)?,store::os_io::ArtifactRef{artifact_id:native.copy_text(row.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:native.copy_text(row.text(3)?)?,standard:native.copy_text(row.text(4)?)?,subset:native.copy_text(row.text(5)?)?}}))}
}
fn order<'a>(rows:&[&'a SqliteRow],index:usize,native:&mut dsl::NativeDecodeControl<'_>)->Result<Vec<&'a SqliteRow>,String>{native.scoped_stage(|native|{native.begin_stage(rows.len().checked_mul(2).ok_or("GIS ordering work overflow")?)?;let mut ordered=native.allocate_vec::<Option<&SqliteRow>>(rows.len())?;ordered.resize(rows.len(),None);for row in rows{native.step()?;let ordinal=usize::try_from(row.integer(index)?).map_err(|_|"GIS ordinal differs")?;if ordinal>=rows.len()||ordered[ordinal].replace(*row).is_some(){return Err("GIS ordinals must be contiguous and unique".into())}}let mut result=native.allocate_vec::<&SqliteRow>(rows.len())?;for row in ordered{native.step()?;result.push(row.ok_or("GIS ordinal missing")?)}Ok(result)})}

impl ArtifactSqliteSnapshot for GisMapSnapshot{
 fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{
  let limits=control.limits();control.checkpoint(SqliteSnapshotPhase::DecodeNative,0,0)?;let length=match payload{store::os_io::IoPayload::Binary(bytes)=>bytes.len(),store::os_io::IoPayload::Text(text)=>text.len()};if length>limits.max_file_bytes{return Err("GIS map native input exceeds file byte limit".into())}
  let mut progress=|state:protocol::native_decoding::NativeDecodeProgress|control.checkpoint(SqliteSnapshotPhase::DecodeNative,state.completed,state.total).is_ok();let mut native=dsl::NativeDecodeControl::new(limits.max_value_bytes,&mut progress);let spec=<Self as store::ArtifactPack>::record_spec().ok_or("GIS map logical RecordSpec missing")?;
  let record=match payload{store::os_io::IoPayload::Binary(bytes)=>{let body=store::semio_format::unwrap_binary_controlled(bytes,"gis.gismap",store::semio_format::Component::Pack,1,&mut native).map_err(|e|e.to_string())?;store::pack_rt::decode_document_controlled(body,&spec,&store::PackDecodeOptions::default(),&mut native).map_err(|e|e.to_string())?.0},store::os_io::IoPayload::Text(text)=>{let body=store::semio_format::split_text_preamble_controlled(text,"gis.gismap",store::semio_format::Component::Dsl,1,&mut native).map_err(|e|e.to_string())?;dsl::schema::parse_exact_controlled(body,&spec,&dsl::ParseOptions{limits:dsl::Limits::default(),mode:dsl::SourceMode::Document},&mut native).map_err(|e|e.message)?}};
  super::owned_pack::reconstruct_record_controlled(&record,&mut native,limits.max_rows)
 }

 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn retire_sqlite_snapshot(self){super::owned_pack::retire(self)}
 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut bound=NativeEncodingBound::new(control)?;bound.add(8192)?;for child in[Some((&self.drawing.child_id,&self.drawing.target)),self.image.as_ref().map(|c|(&c.child_id,&c.target)),Some((&self.value.child_id,&self.value.target))].into_iter().flatten(){for v in[child.0,&child.1.artifact_id,&child.1.dialect.artifact_kind,&child.1.dialect.standard,&child.1.dialect.subset]{bound.repeated(v.len(),6)?;}}let mut pending=vec![];for feature in self.positions.iter().chain(&self.routes).chain(&self.regions){bound.add(128)?;bound.repeated(feature.id.len(),6)?;pending.push(&feature.data);}while let Some(value)=pending.pop(){bound.add(512)?;match value{dsl::DslValue::Null|dsl::DslValue::Bool(_)|dsl::DslValue::Number(_)=>{},dsl::DslValue::String(v)=>bound.repeated(v.len(),6)?,dsl::DslValue::Bytes(v)=>bound.repeated(v.len(),2)?,dsl::DslValue::Array(v)=>{bound.repeated(v.len(),32)?;pending.extend(v)},dsl::DslValue::Object(v)=>{bound.repeated(v.len(),96)?;for(name,value)in v{bound.repeated(name.len(),6)?;pending.push(value);}}}}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;preflight(self,control)?;let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert(TABLES[0],&[])?;child(&mut p,TABLES[5],&self.drawing)?;if let Some(c)=&self.image{child(&mut p,TABLES[6],c)?;}child(&mut p,TABLES[7],&self.value)?;let mut pending=VecDeque::new();let mut next=1i64;for(table,features)in[(2,&self.positions),(3,&self.routes),(4,&self.regions)]{for(ordinal,feature)in features.iter().enumerate(){let id=next;next=next.checked_add(1).ok_or("GIS Value identity overflow")?;p.insert(TABLES[table],&[Cell::Integer(1),Cell::Integer(ordinal as i64),Cell::Text(&feature.id),Cell::Integer(id)])?;pending.push_back((id,&feature.data));}}
 while let Some((id,value))=pending.pop_front(){p.insert_key(TABLES[1],id,&[Cell::Text(kind(value))])?;match value{dsl::DslValue::Null=>p.insert_key(TABLES[8],id,&[])?,dsl::DslValue::Bool(v)=>p.insert_key(TABLES[9],id,&[Cell::Integer(i64::from(*v))])?,dsl::DslValue::Number(Number::UInt(v))=>p.insert_key(TABLES[10],id,&[Cell::Integer((v>>32)as i64),Cell::Integer((v&0xffff_ffff)as i64)])?,dsl::DslValue::Number(Number::Int(v))=>p.insert_key(TABLES[11],id,&[Cell::Integer(*v)])?,dsl::DslValue::Number(Number::Float(v))=>insert_key_ieee754(&mut p,TABLES[12],id,&[Cell::Real(*v)],FLOAT)?,dsl::DslValue::String(v)=>p.insert_key(TABLES[13],id,&[Cell::Text(v)])?,dsl::DslValue::Bytes(v)=>{p.insert_key(TABLES[14],id,&[])?;for(ordinal,value)in v.iter().enumerate(){p.insert(TABLES[15],&[Cell::Integer(id),Cell::Integer(ordinal as i64),Cell::Integer(i64::from(*value))])?;}},dsl::DslValue::Array(v)=>{p.insert_key(TABLES[16],id,&[])?;for(ordinal,value)in v.iter().enumerate(){let key=next;next=next.checked_add(1).ok_or("GIS Value identity overflow")?;p.insert(TABLES[17],&[Cell::Integer(id),Cell::Integer(ordinal as i64),Cell::Integer(key)])?;pending.push_back((key,value));}},dsl::DslValue::Object(v)=>{p.insert_key(TABLES[18],id,&[])?;for(ordinal,(name,value))in v.iter().enumerate(){let key=next;next=next.checked_add(1).ok_or("GIS Value identity overflow")?;p.insert(TABLES[19],&[Cell::Integer(id),Cell::Integer(ordinal as i64),Cell::Text(name),Cell::Integer(key)])?;pending.push_back((key,value));}}}p.checkpoint()?;}p.finish()}
 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String>{validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits()).map_err(|e|e.to_string())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;let maximum=control.limits().max_value_bytes;let total=database.tables.iter().map(|v|v.rows.len()).sum();let mut callback=|p:protocol::native_decoding::NativeDecodeProgress|control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,p.completed,p.total).is_ok();let mut native=dsl::NativeDecodeControl::new(maximum,&mut callback);native.begin_stage(total)?;let mut read=Read::new(database,&mut native)?;native.begin_stage(total)?;if read.tables[0].rows.len()!=1{return Err("GIS document ownership differs".into())}let root=read.tables[0].rows[0].rowid;read.take(0,root,&mut native)?;let drawing=read.child(5,root,&mut native)?;let value=read.child(7,root,&mut native)?;if read.tables[6].rows.len()>1{return Err("GIS image ownership differs".into())}let image=if read.tables[6].rows.is_empty(){None}else{Some(read.child(6,root,&mut native)?)};
 let mut feature_rows=native.allocate_vec::<Vec<&SqliteRow>>(3)?;let mut pending=native.allocate_vec::<i64>(read.tables[1].rows.len())?;for table in[2,3,4]{let mut refs=native.allocate_vec::<&SqliteRow>(read.tables[table].rows.len())?;refs.extend(read.tables[table].rows.iter());let rows=order(&refs,2,&mut native)?;for row in&rows{read.take(table,row.rowid,&mut native)?;if row.integer(1)?!=root{return Err("GIS feature owner differs".into())}if pending.len()>=read.tables[1].rows.len(){return Err("GIS feature roots exceed owned values".into())}pending.push(row.integer(4)?);}feature_rows.push(rows);}
 let mut groups=BTreeMap::<(usize,i64),Vec<&SqliteRow>>::new();for table in[15,17,19]{native.charge(read.tables[table].rows.len().checked_mul(144).ok_or("GIS relationship lookup overflow")?)?;native.scoped_stage(|native|{native.begin_stage(read.tables[table].rows.len())?;for row in&read.tables[table].rows{native.step()?;groups.entry((table,row.integer(1)?)).or_default().push(row);}Ok::<(),String>(())})?;}
 struct Plan<'a>{id:i64,kind:&'a str,row:&'a SqliteRow,relations:Vec<&'a SqliteRow>,children:Vec<i64>}
 let mut plans=native.allocate_vec::<Plan>(read.tables[1].rows.len())?;while let Some(id)=pending.pop(){let header=read.take(1,id,&mut native)?;let kind=header.text(1)?;let table=match kind{"null"=>8,"boolean"=>9,"unsigned"=>10,"signed"=>11,"float"=>12,"text"=>13,"bytes"=>14,"array"=>16,"object"=>18,_=>return Err("GIS native Value variant differs".into())};let row=read.take(table,id,&mut native)?;let edge=match kind{"bytes"=>Some(15),"array"=>Some(17),"object"=>Some(19),_=>None};let mut children=Vec::new();let relations=if let Some(table)=edge{let rows=groups.remove(&(table,id)).unwrap_or_default();let relations=order(&rows,2,&mut native)?;children=native.allocate_vec::<i64>(if kind=="bytes"{0}else{relations.len()})?;for relation in&relations{read.take(table,relation.rowid,&mut native)?;if kind!="bytes"{children.push(relation.integer(if kind=="object"{4}else{3})?);}}relations}else{vec![]};if pending.len().checked_add(children.len()).and_then(|n|n.checked_add(plans.len())).ok_or("GIS frontier overflow")?>read.tables[1].rows.len(){return Err("GIS frontier exceeds owned values".into())}pending.extend(children.iter().rev().copied());plans.push(Plan{id,kind,row,relations,children});}
 if read.used.len()!=total{return Err("GIS has unowned entity rows".into())}native.begin_stage(plans.len())?;let mut forest=Forest(native.allocate_vec::<Option<dsl::DslValue>>(plans.len())?);forest.0.resize_with(plans.len(),||None);let mut indices=BTreeMap::new();native.charge(plans.len().checked_mul(48).ok_or("GIS topology lookup overflow")?)?;native.scoped_stage(|native|{native.begin_stage(plans.len())?;for(index,p)in plans.iter().enumerate(){native.step()?;indices.insert(p.id,index);}Ok::<(),String>(())})?;
 let take=|forest:&mut Forest,id:i64|->Result<dsl::DslValue,String>{let index=*indices.get(&id).ok_or("GIS native child missing")?;forest.0[index].take().ok_or_else(||"GIS Value topology differs".into())};for(index,p)in plans.into_iter().enumerate().rev(){native.step()?;let value=match p.kind{"null"=>dsl::DslValue::Null,"boolean"=>{let n=p.row.integer(1)?;if n!=0&&n!=1{return Err("GIS boolean differs".into())}dsl::DslValue::Bool(n==1)},"unsigned"=>{let high=u32::try_from(p.row.integer(1)?).map_err(|_|"GIS unsigned word differs")?;let low=u32::try_from(p.row.integer(2)?).map_err(|_|"GIS unsigned word differs")?;dsl::DslValue::Number(Number::UInt((u64::from(high)<<32)|u64::from(low)))},"signed"=>dsl::DslValue::Number(Number::Int(p.row.integer(1)?)),"float"=>dsl::DslValue::Number(Number::Float(FloatRow::new(p.row,FLOAT)?.real(1)?)),"text"=>dsl::DslValue::String(native.copy_text(p.row.text(1)?)?),"bytes"=>{let mut bytes=native.allocate_vec::<u8>(p.relations.len())?;native.scoped_stage(|native|{native.begin_stage(p.relations.len())?;for row in p.relations{native.step()?;bytes.push(u8::try_from(row.integer(3)?).map_err(|_|"GIS octet differs")?);}Ok::<(),String>(())})?;dsl::DslValue::Bytes(bytes)},"array"=>{let mut values=Items(native.allocate_vec::<dsl::DslValue>(p.children.len())?);native.scoped_stage(|native|{native.begin_stage(p.children.len())?;for id in p.children{native.step()?;values.0.push(take(&mut forest,id)?)}Ok::<(),String>(())})?;dsl::DslValue::Array(std::mem::take(&mut values.0))},"object"=>{let mut values=Members(native.allocate_vec::<(String,dsl::DslValue)>(p.children.len())?);native.scoped_stage(|native|{native.begin_stage(p.children.len())?;for(id,row)in p.children.into_iter().zip(p.relations){native.step()?;let name=native.copy_text(row.text(3)?)?;values.0.push((name,take(&mut forest,id)?));}Ok::<(),String>(())})?;dsl::DslValue::Object(std::mem::take(&mut values.0))},_=>return Err("GIS variant differs".into())};forest.0[index]=Some(value);}
 native.begin_stage(feature_rows.iter().map(Vec::len).sum())?;let mut output=native.allocate_vec::<Features>(3)?;for rows in feature_rows{let mut features=Features(native.allocate_vec::<MapFeature>(rows.len())?);for row in rows{native.step()?;let id=native.copy_text(row.text(3)?)?;features.0.push(MapFeature{id,data:take(&mut forest,row.integer(4)?)?});}output.push(features);}if forest.0.iter().any(Option::is_some){return Err("GIS feature roots differ".into())}native.checkpoint()?;let mut out=output.into_iter();let mut positions=out.next().ok_or("GIS positions missing")?;let mut routes=out.next().ok_or("GIS routes missing")?;let mut regions=out.next().ok_or("GIS regions missing")?;Ok(Self{positions:std::mem::take(&mut positions.0),routes:std::mem::take(&mut routes.0),regions:std::mem::take(&mut regions.0),drawing,image,value})}
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,0)?;if dialect.artifact_kind!="s.gis.gismap"||dialect.standard!="1"||dialect.subset!="*"{return Err(String::from("GIS map does not own this semantic subset").into())}let expected=self.to_sqlite_database(control)?;let mut owned=dsl::__rt::DecodedFieldOwner::new(Self::from_sqlite_database(database,control)?,Self::retire_sqlite_snapshot);let actual=owned.as_mut().to_sqlite_database(control)?;if expected!=actual{return Err(String::from("GIS complete typed identity differs").into())}Ok(store::io_schema::IoOutcome::clean(()))}
}
